WITH parsed AS (SELECT id, currency, tier_limits, tier_prices, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE currency IN ('EUR', 'USD', 'THB')) SELECT *, SUM(entry_price) OVER (PARTITION BY currency ORDER BY lowest_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_entry_price, NTILE(10) OVER (PARTITION BY currency ORDER BY lowest_price, id) AS lowest_price_bucket, RANK() OVER (PARTITION BY currency ORDER BY entry_price DESC NULLS LAST) AS entry_price_rank FROM parsed;
